  "holds": [
    "24 routes mint evaluator3 StepTermination and command-envelope:3 failure envelopes",
    "operational-failed rows carry non-none faultCause; request-rejected rows do not",
    "promised-bytes-lost:provider-return and input-identity-invalid:evidence-store refuse EVALUATOR_FAULT_ORIGIN",
    "complete-replay-mismatch:host-internal is SYSTEM.OUTCOME.ILLEGAL_STATE/host-invariant, not HOST.IO_FAILURE",
    "output-bound-exceeded:host-serialization is OUTPUT.SERIALIZATION_FAILED/output-serialization/EVALUATION.OUTPUT_BOUND_EXCEEDED",
    "used DomainDetail codes are in both common and evaluator3 DomainDetailCode enums",
    "kind=failure without errors is refused by command-envelope3"
  ],
  "must": [],
  "should": [
    {
      "id": "S1-schema-admits-illegal-pairs",
      "severity": "SHOULD",
      "title": "JSON Schema admits illegal condition/origin pairs; only route() refuses",
      "counterexample": {
        "observation": {
          "condition": "promised-bytes-lost",
          "origin": "provider-return",
          "reference": "retained:fixture",
          "limit": null
        },
        "C.validate": "ADMIT",
        "route": "AdmissionError:EVALUATOR_FAULT_ORIGIN"
      },
      "also": "input-identity-invalid:evidence-store is likewise schema-valid and model-refused"
    },
    {
      "id": "S2-owner-carrier-remedy-drift",
      "severity": "SHOULD",
      "title": "owner-carrier checks ADMIT while DomainDetail.remedy disagrees with identity carriers",
      "counterexample": {
        "promised-bytes-lost": {
          "class_error_cause_code_subject": "equal",
          "faultRemedy": "Restore the referenced promised evidence bytes or rerun the producing stage.",
          "identityRemedy": "Restore the exact retained closure bytes or report their unavailability."
        },
        "complete-replay-mismatch": {
          "class_error_cause_code_subject": "equal",
          "faultRemedy": "Preserve the disagreement and regenerate from admitted retained inputs; do not reuse the mismatching Run.",
          "identityRemedy": "Retain the sealed Run and investigate the differing regeneration result."
        }
      }
    },
    {
      "id": "S3-origin-spelling-not-native",
      "severity": "SHOULD",
      "title": "Fault origin enum is not native possibleOrigins; public_termination_for cannot consume it",
      "counterexample": {
        "overlap": ["external-configuration"],
        "faultOnly": ["evidence-store", "external-specification", "host-internal", "host-pre-plan", "host-serialization", "provider-return", "release-declaration", "retained-regeneration"],
        "nativeOnly": ["authenticated-release-declaration", "externally-supplied-spec", "host-generated-internal-layer", "producer-boundary"],
        "nativeExternallySuppliedSpec": {
          "class": "request-rejected",
          "errorCode": "REQUEST.PRECONDITION_FAILED",
          "domainDetail": null,
          "envelopeDetail": "native.capability-spec-invalid"
        },
        "faultExternalSpecification": {
          "class": "request-rejected",
          "errorCode": "REQUEST.PRECONDITION_FAILED",
          "detail": "EVALUATION.INPUT_REFUSED"
        }
      }
    },
    {
      "id": "S4-replay-mismatch-null-reference",
      "severity": "SHOULD",
      "title": "complete-replay-mismatch allows reference null and drops subject; identity RegenerationMismatch always names the Run",
      "counterexample": {
        "observation": {"condition": "complete-replay-mismatch", "origin": "retained-regeneration", "reference": null, "limit": null},
        "schema": "ADMIT",
        "domainDetail": {
          "code": "evidence.regeneration-mismatch",
          "hasSubject": false
        }
      }
    },
    {
      "id": "S5-pointer-omission-uses-input-refused",
      "severity": "SHOULD",
      "title": "Required output pointer omission projects EVALUATION.INPUT_REFUSED",
      "counterexample": {
        "route": "required-output-pointer-omitted:provider-return",
        "errorCode": "PROVIDER.PROTOCOL_VIOLATION",
        "faultCause": "provider-protocol",
        "detail": "EVALUATION.INPUT_REFUSED"
      }
    },
    {
      "id": "S6-output-bound-has-no-limit-object",
      "severity": "SHOULD",
      "title": "output-bound-exceeded carries no field/observed/maximum; within-bound selection-limit is schema-valid",
      "counterexample": {
        "outputBoundDetail": {
          "code": "EVALUATION.OUTPUT_BOUND_EXCEEDED",
          "hasLimit": false,
          "hasSubject": false
        },
        "selectionLimitObservedEqualsMaximum": {
          "limit": {"field": "selectedPrograms", "observed": 64, "maximum": 64},
          "schema": "ADMIT",
          "route": "EVALUATOR_FAULT_NOT_OVER_LIMIT"
        }
      }
    }
  ],
  "advisory": [
    "Checker uses one synthetic diagnostic blob for every route; hash custody is shown, content is not interpreted",
    "owner-carrier tests do not pass EvidenceUnavailable/RegenerationMismatch exceptions into route(); they rebuild a matching observation",
    "limit.field is an open string, not a closed published-bound vocabulary",
    "kind=failure does not forbid a run property; a placeholder run failed AnalysisResult oneOf, which does not prove the policy",
    "evaluator3 common isolated-additions prose and workflow-projection-contract appendix omit EVALUATION.INPUT_REFUSED and EVALUATION.SELECTION_LIMIT even though both enums contain them",
    "evaluator_composition_model.v3.py still raises AdmissionError('EVALUATION.OUTPUT_BOUND_EXCEEDED') as a string, not via this observation"
  ],
  "coverageLimits": [
    "four fault files plus named owner registries only",
    "no host execution, no Run reconstruct, no D9 successor publication",
    "checker count 33 is not acceptance",
    "origin-law check is table comparison plus the two identity carriers, not every native public_termination_for key",
    "execution-input v3 not reviewed in this turn"
  ]
}
